import{obterJSON,endereco,consultaLimpa,pontuarCorrespondencia,idiomas}from'./comum.js';
const lista=v=>Array.isArray(v)?v:v==null?[]:[v];
const sim=v=>{const n=String(Array.isArray(v)?v[0]:v??'').trim().toLowerCase();return v===true||['true','yes','y','1','authorized','available'].includes(n)};
export function converterEric(item){
 const id=String(item?.id||'').trim();if(!/^E[DJ]\d+/i.test(id)||!sim(item?.efulltextauth))return null;
 const pagina=endereco(`https://eric.ed.gov/?id=${encodeURIComponent(id)}`),pdf=endereco(`https://files.eric.ed.gov/fulltext/${encodeURIComponent(id)}.pdf`);if(!pagina||!pdf)return null;
 const autores=lista(item?.author).flatMap(v=>String(v||'').split(/\s*;\s*/)).map(x=>x.trim()).filter(Boolean),tipos=lista(item?.publicationtype).map(String).filter(Boolean),ano=String(item?.publicationdateyear||'').trim(),descricao=[String(item?.description||'').trim(),tipos.slice(0,2).join(' · '),ano].filter(Boolean).join(' · ');
 return{id:`eric:${id}`,fonte:'eric',provedor:'ERIC · U.S. Department of Education',titulo:String(item?.title||'Sem título'),autores,idiomas:idiomas(lista(item?.language)),capa:null,descricao,acessoLivre:true,dominioPublico:false,tipoAcesso:'Material educacional · texto integral',licenca:'O ERIC indica texto integral disponível gratuitamente. Direitos autorais e condições de reutilização continuam sendo os informados no próprio documento.',origem:pagina,ler:pdf,texto:null,formatos:[{tipo:'PDF',url:pdf}]};
}
export async function pesquisarEric(q,o={}){const termo=consultaLimpa(q);if(!termo)return{livros:[],total:0,temMais:false};const pagina=Math.max(1,o.pagina||1),u=new URL('/api/acervos-gratuitos',location.origin);u.searchParams.set('fonte','eric');u.searchParams.set('q',termo);u.searchParams.set('pagina',String(pagina));const d=await obterJSON(u,14000,2),docs=Array.isArray(d?.response?.docs)?d.response.docs:Array.isArray(d?.docs)?d.docs:Array.isArray(d?.records)?d.records:[],livros=docs.map(converterEric).filter(Boolean);for(const l of livros)l.relevancia=pontuarCorrespondencia(termo,l.titulo,l.autores);livros.sort((a,b)=>(b.relevancia||0)-(a.relevancia||0));const total=Number(d?.response?.numFound??d?.numFound??docs.length)||livros.length;return{livros,total,temMais:pagina*40<total&&docs.length>0}}
